import{_ as i,a0 as t,w as o,s as r,I as n,x as a,a1 as e,A as l,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"用 Lua 解析參數 | LCTT x X-CMD","titleTemplate":false,"description":"用 Lua 解析參數 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Lua 解析參數 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Lua 解析參數 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221129.3 ⭐️⭐️ Parse arguments with Lua","title":"用 Lua 解析參數","tag":"202212","desc":""},"relativePath":"202212/20221129.3 ⭐️⭐️ Parse arguments with Lua.md","filePath":"[post].md"}'),u={name:"202212/20221129.3 ⭐️⭐️ Parse arguments with Lua.md"};function g(c,s,h,m,f,b){const p=t("Link");return o(),r("div",null,[s[27]||(s[27]=n("h1",{id:"用-lua-解析參數",tabindex:"-1"},[a("用 Lua 解析參數 "),n("a",{class:"header-anchor",href:"#用-lua-解析參數","aria-label":"Permalink to “用 Lua 解析參數”"},"​")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202212/06/111552sofsllzdfffgfakh.jpg",alt:""})],-1)),s[29]||(s[29]=n("blockquote",null,[n("p",null,[a("參數對於交互式計算至關重要，Lua 編程語言提供了 "),n("code",null,"{...}"),a(" 表達式來封裝在啓動 Lua 腳本時給定的可變參數。")])],-1)),n("p",null,[s[2]||(s[2]=a("大多數計算機命令由兩部分組成：命令和參數。命令是要執行的程序，而參數可能是命令選項或用户輸入。如果沒有這種結構，用户將不得不編輯命令的代碼，以改變命令所處理的數據。想像一下重寫 ",-1)),e(p,{href:"https://opensource.com/article/20/8/printf"},{default:l(()=>[...s[0]||(s[0]=[a("printf",-1)])]),_:1}),s[3]||(s[3]=a(" 命令只是為了讓你的計算機用 “hello world” 消息問候你。參數對於交互式計算至關重要，",-1)),e(p,{href:"https://opensource.com/article/22/11/lua-worth-learning"},{default:l(()=>[...s[1]||(s[1]=[a("Lua 編程語言",-1)])]),_:1}),s[4]||(s[4]=a(" 提供了 ",-1)),s[5]||(s[5]=n("code",null,"{...}",-1)),s[6]||(s[6]=a(" 表達式來封裝在啓動 Lua 腳本時給定的可變參數。",-1))]),s[30]||(s[30]=d(`<h3 id="在-lua-中使用參數" tabindex="-1">在 Lua 中使用參數 <a class="header-anchor" href="#在-lua-中使用參數" aria-label="Permalink to “在 Lua 中使用參數”">​</a></h3><p>幾乎每一個給計算機的命令都假定一個參數，即使它期望參數是一個空列表。 Lua 會記錄啓動後寫入的內容，即使你可能對這些參數不做任何操作。要在 Lua 啓動時使用用户提供的參數，請迭代 <code>{...}</code> 表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local args = {...}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for i,v in ipairs(args) do</span></span>
<span class="line"><span>    print(v)</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>運行代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./myargs.lua</span></span>
<span class="line"><span>$ lua ./myargs.lua foo --bar baz</span></span>
<span class="line"><span>foo</span></span>
<span class="line"><span>--bar</span></span>
<span class="line"><span>baz</span></span>
<span class="line"><span>----</span></span></code></pre></div><p>參數是不安全的，Lua 會完全按照輸入的方式打印所有參數。</p><h3 id="解析參數" tabindex="-1">解析參數 <a class="header-anchor" href="#解析參數" aria-label="Permalink to “解析參數”">​</a></h3><p>對於簡單的命令，Lua 的基本功能足以解析和處理參數。這是一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-- setup</span></span>
<span class="line"><span></span></span>
<span class="line"><span>local args = {...}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- engine</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function echo(p)</span></span>
<span class="line"><span>   print(p)</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- go</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for i,v in ipairs(args) do</span></span>
<span class="line"><span>  print(i .. &quot;: &quot; .. v)</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for i,v in ipairs(args) do</span></span>
<span class="line"><span>  if args[i] == &quot;--say&quot; then</span></span>
<span class="line"><span>    echo(&quot;echo: &quot; .. args[i+1])</span></span>
<span class="line"><span>  end</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>在 <code>setup</code> 部分，將所有命令參數轉儲到名為 <code>args</code> 的變量中。</p><p>在 <code>engine</code> 部分，創建一個名為 <code>echo</code> 的函數，用於打印你“輸入”其中的任何內容。</p><p>最後，在 <code>go</code> 部分，解析 <code>args</code> 變量（用户在啓動時提供的參數）中的索引和值。在此示例代碼中，為清楚起見，第一個 <code>for</code> 循環僅打印每個索引和值。</p><p>第二個 <code>for</code> 循環使用索引來檢查第一個參數，它被假定是一個選項。此示例代碼中唯一有效的選項是 <code>--say</code>。如果循環找到字符串 <code>--say</code>，它會調用 <code>echo</code> 函數，並將當前參數的索引 <em>加 1</em>（<em>下一個</em> 參數）作為函數參數提供。</p><p>命令參數的分隔符是一個或多個空格。運行代碼查看結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./echo.lua --say zombie apocalypse</span></span>
<span class="line"><span>1: --say</span></span>
<span class="line"><span>2: zombie</span></span>
<span class="line"><span>3: apocalypse</span></span>
<span class="line"><span>echo: zombie</span></span></code></pre></div><p>大多數用户都知道在向計算機發出命令時空格很重要，因此在這種情況下刪除第三個參數是預期的行為。下面是演示兩種有效“轉義”方法的變體：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./echo.lua --say &quot;zombie apocalypse&quot;</span></span>
<span class="line"><span>1: --say</span></span>
<span class="line"><span>2: zombie apocalypse</span></span>
<span class="line"><span>echo: zombie apocalypse</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ lua ./echo.lua --say zombie\\ apocalypse</span></span>
<span class="line"><span>1: --say</span></span>
<span class="line"><span>2: zombie apocalypse</span></span>
<span class="line"><span>echo: zombie apocalypse</span></span></code></pre></div><h3 id="解析參數-1" tabindex="-1">解析參數 <a class="header-anchor" href="#解析參數-1" aria-label="Permalink to “解析參數”">​</a></h3><p>手動解析參數簡單且無依賴性。但是，你必須考慮一些細節。大多數現代命令都允許使用短選項（例如，<code>-f</code>）和長選項（<code>--foo</code>），並且大多數命令都提供 <code>-h</code> 或 <code>--help</code> 或者在沒有所需參數時顯示幫助菜單。</p>`,19)),n("p",null,[s[9]||(s[9]=a("使用 ",-1)),e(p,{href:"https://opensource.com/article/19/11/getting-started-luarocks"},{default:l(()=>[...s[7]||(s[7]=[a("LuaRocks",-1)])]),_:1}),s[10]||(s[10]=a(" 可以輕鬆安裝其他庫。有一些非常好的工具，例如 ",-1)),e(p,{href:"https://opensource.com/article/21/8/parsing-commands-lua"},{default:l(()=>[...s[8]||(s[8]=[a("alt-getopt",-1)])]),_:1}),s[11]||(s[11]=a("，它們為解析參數提供了額外的基礎設施。",-1))]),s[31]||(s[31]=n("hr",null,null,-1)),n("p",null,[s[13]||(s[13]=a("via: ",-1)),e(p,{href:"https://opensource.com/article/22/11/lua-command-arguments"},{default:l(()=>[...s[12]||(s[12]=[a("https://opensource.com/article/22/11/lua-command-arguments",-1)])]),_:1})]),n("p",null,[s[18]||(s[18]=a("作者：",-1)),e(p,{href:"https://opensource.com/users/seth"},{default:l(()=>[...s[14]||(s[14]=[a("Seth Kenlon",-1)])]),_:1}),s[19]||(s[19]=a(" 選題：",-1)),e(p,{href:"https://github.com/lkxed"},{default:l(()=>[...s[15]||(s[15]=[a("lkxed",-1)])]),_:1}),s[20]||(s[20]=a(" 譯者：",-1)),e(p,{href:"https://github.com/geekpi"},{default:l(()=>[...s[16]||(s[16]=[a("geekpi",-1)])]),_:1}),s[21]||(s[21]=a(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[24]||(s[24]=a("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[22]||(s[22]=[a("LCTT",-1)])]),_:1}),s[25]||(s[25]=a(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:l(()=>[...s[23]||(s[23]=[a("Linux中國",-1)])]),_:1}),s[26]||(s[26]=a(" 榮譽推出",-1))])])}const C=i(u,[["render",g]]);export{L as __pageData,C as default};
